"""Crew 3: Company Research - 3 agents, 4 tasks (+ optional tech task, --lite)."""
from _compat import Agent, Task, Crew, Process, get_serper_tool, get_scrape_tool, set_meta
from core.model_router import get_llm, tier_for, max_iter_for
from user_profile import skills_as_text, MY_SKILLS
GUARD_SEARCH = "Use only publicly available information (company websites, job postings, press releases). Do not collect personal contact details, such as emails, phone numbers, or personal profiles, of individuals."

def build_crew(company_name="Google", lite=False, industry=None, economy=False):
    def mk(role,goal,backstory,tools,key):
        return Agent(role=role,goal=goal,backstory=backstory,tools=tools,verbose=True,llm=get_llm(tier_for(key,economy),economy),max_iter=max_iter_for("research",economy))
    company_researcher = mk("Company Intelligence Analyst","Gather comprehensive information about companies including their business model, culture, recent developments, and strategic priorities","You are an expert at researching companies quickly and thoroughly. You know where to find reliable information and how to synthesize it into insights that help job candidates understand what it's really like to work there.",[get_serper_tool(), get_scrape_tool()],"company_researcher")
    culture_analyst = mk("Company Culture Specialist","Analyze company culture, values, and employee experience to determine cultural fit and identify potential talking points","You are skilled at reading between the lines of corporate communications and employee feedback to understand what a company's culture is really like. You can identify both positive aspects and potential red flags.",[get_serper_tool(), get_scrape_tool()],"culture_analyst")
    talking_points_generator = mk("Interview Preparation Specialist","Transform company research into specific talking points and questions that demonstrate genuine interest and knowledge","You excel at identifying the most compelling aspects of company research and turning them into conversation starters and demonstration points for interviews and applications.",[],"talking_points_generator")  # content_synthesizer, question_generator dropped
    agents=[company_researcher, culture_analyst]; tasks=[]
    task_map={}
    if industry=="tech":
        tech_agent = Agent(role="Tech Industry Analyst",goal="Research company tech stack, engineering culture, and recent product developments",backstory="You understand startup culture, technical challenges, and what engineers value in workplaces",tools=[get_serper_tool()],verbose=True,llm=get_llm("cheap",economy),max_iter=max_iter_for("research",economy))
        agents.insert(0, tech_agent)
        t = Task(description="Research {company_name}'s technology stack, engineering culture, and recent product developments using public sources such as their engineering blog, open-source activity, and job postings. Cite sources and mark anything unverified. "+GUARD_SEARCH, agent=tech_agent, expected_output="A sourced summary of the company's tech stack, engineering culture, and recent product developments")
        set_meta(t, "task_name", "tech_stack_research_task"); tasks.append(t); task_map["tech_stack_research_task"]=t
    research_company_task = Task(description="Research {company_name} thoroughly and compile a comprehensive profile including: 1) Business model and main products/services, 2) Company size, locations, and organizational structure, 3) Financial health and recent performance, 4) Key leadership and management team, 5) Recent news, press releases, and major developments, 6) Competitors and market position, 7) Growth trajectory and future plans. Cite source URLs and mark anything that could not be verified. "+GUARD_SEARCH, agent=company_researcher, expected_output="A detailed company profile with all key business information organized clearly")
    set_meta(research_company_task, "task_name", "research_company_task"); tasks.append(research_company_task); task_map["research_company_task"]=research_company_task
    analyze_culture_task = Task(description="Analyze {company_name}'s culture and values by examining: 1) Official company values and mission statements, 2) Employee reviews on Glassdoor and similar platforms, 3) LinkedIn posts and employee engagement, 4) Diversity and inclusion initiatives, 5) Work-life balance indicators, 6) Career development opportunities, 7) Management style and communication patterns. Identify both strengths and potential concerns. Separate sourced findings from inferences; say plainly when review sites or LinkedIn could not be accessed. "+GUARD_SEARCH, agent=culture_analyst, expected_output="A balanced analysis of company culture with specific examples and insights about what it's like to work there", context=[research_company_task])
    set_meta(analyze_culture_task, "task_name", "analyze_culture_task"); tasks.append(analyze_culture_task); task_map["analyze_culture_task"]=analyze_culture_task
    if not lite:
        agents.append(talking_points_generator)
        generate_talking_points_task = Task(description="Based on the research about {company_name}, create: 1) 5 specific talking points that show knowledge of the company, 2) 3 thoughtful questions to ask during interviews, 3) 2-3 ways to connect your background to their current priorities, 4) Key culture elements to emphasize in your application, 5) Recent developments to reference in cover letters or interviews.", agent=talking_points_generator, expected_output="A practical list of talking points, questions, and connection opportunities ready to use in applications and interviews", context=[research_company_task, analyze_culture_task])
        set_meta(generate_talking_points_task, "task_name", "generate_talking_points_task"); tasks.append(generate_talking_points_task); task_map["generate_talking_points_task"]=generate_talking_points_task
        prefs = skills_as_text()
        assess_alignment_task = Task(description="Compare {company_name}'s culture and values with the candidate's preferences and values. Identify: 1) Areas of strong alignment, 2) Potential culture fit concerns, 3) Questions to explore during interviews, 4) How to authentically position yourself as a cultural fit, 5) Red flags or deal-breakers to consider. Candidate preferences:\n"+prefs, agent=culture_analyst, expected_output="An honest assessment of cultural fit with specific recommendations for how to approach this opportunity", context=[analyze_culture_task, generate_talking_points_task])
        set_meta(assess_alignment_task, "task_name", "assess_alignment_task"); tasks.append(assess_alignment_task); task_map["assess_alignment_task"]=assess_alignment_task
    crew=Crew(agents=agents,tasks=tasks,process=Process.sequential,verbose=True); set_meta(crew, "task_map", task_map); return crew
build_company_research_crew = build_crew
